import codecs
input()
mapping = codecs.charmap_build('\0A')
for operation in [lambda: codecs.charmap_build(), lambda: codecs.charmap_build('a', 'b'), lambda: codecs.charmap_build(map='a'), lambda: codecs.charmap_build(''), lambda: codecs.charmap_build(None), lambda: mapping.size(None), lambda: mapping.size(unused=None)]:
    try:
        operation()
    except Exception as error:
        print(type(error).__name__, error.args, error.__cause__, error.__context__, error.__traceback__ is not None)
print(type(mapping).__name__, mapping.size(), codecs.charmap_encode('\0A', 'strict', mapping))
for table in ['abc', '\0AA', '\0\ufffeA', '\0\U0001f600', 'A' * 257]:
    encoder = codecs.charmap_build(table)
    print(type(encoder).__name__)
    for text in ['A', '\0', '\U0001f600']:
        try:
            print(codecs.charmap_encode(text, 'strict', encoder))
        except UnicodeEncodeError as error:
            print(error.encoding, error.object, error.start, error.end, error.reason)
